<?php

namespace App\Support;

/**
 * Countries and their cities for the Get Started form, from resources/data/geo
 * (generated by resources/data/geo/build.cjs).
 */
class Geo
{
    /** @return array<int, array{code: string, name: string}> sorted by name */
    public static function countries(): array
    {
        static $countries;

        return $countries ??= json_decode(file_get_contents(resource_path('data/geo/countries.json')), true);
    }

    public static function countryNames(): array
    {
        return array_column(self::countries(), 'name');
    }

    /** City names for an ISO country code; empty when the dataset has none. */
    public static function cities(string $code): array
    {
        $path = resource_path('data/geo/cities/' . strtoupper($code) . '.json');

        return preg_match('/^[A-Za-z]{2}$/', $code) && is_file($path)
            ? json_decode(file_get_contents($path), true)
            : [];
    }
}
